CREATE OR REPLACE FUNCTION public.guard_gateway_ambiguous_failover() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_exists boolean; v_base text; BEGIN v_base:=split_part(NEW.idempotency_key,':',1); IF NEW.idempotency_key IS NULL OR v_base='' THEN RETURN NEW; END IF; SELECT EXISTS (SELECT 1 FROM public.gateway_payment_attempts a WHERE a.user_id=NEW.user_id AND split_part(a.idempotency_key,':',1)=v_base AND a.id<>NEW.id AND a.failure_class IN ('timeout','technical','unavailable','unknown')) INTO v_exists; IF v_exists THEN RAISE EXCEPTION 'ambiguous_gateway_attempt_requires_status_recovery'; END IF; IF NEW.failure_class IN ('timeout','technical','unavailable','unknown') THEN INSERT INTO public.gateway_recovery_queue(user_id,attempt_id,transaction_id,gateway_id,provider,idempotency_key,failure_class,external_transaction_id) VALUES (NEW.user_id,NEW.id,NEW.transaction_id,NEW.gateway_id,NEW.gateway_name,NEW.idempotency_key,NEW.failure_class,NEW.external_transaction_id) ON CONFLICT (user_id,attempt_id) DO NOTHING; END IF; RETURN NEW; END; $$;